                c.drawText("\u2709", 8 * px, top + (11 + 17) * px, p); // sim .mailGlyph
                float tx = 40 * px;
                p.setFakeBoldText(true);
                p.setTextSize(18 * px);
                c.drawText(ellipsize(displayName(m.address), w - tx - 6 * px, p), tx, top + 3 * px + 18 * px, p);
