    private void drawNfLabel(Canvas c, float x, float baseY, String text, float vh) {
        // HTML .nfLabel: plain white label above each form field.
        p.setTypeface(Typeface.create("sans-serif-condensed", Typeface.NORMAL));
        p.setFakeBoldText(false);
        p.setColor(Color.WHITE);
        p.setTextSize(1.6f * vh);
        p.setTextAlign(Paint.Align.LEFT);
        c.drawText(text, x, baseY, p);
        p.setTypeface(Typeface.DEFAULT);
    }

    private void drawCalnoteForm(Canvas c, int w, int h) {
        // HTML calnote page: the Reminder/Meeting/... form.
        float vh = h / 100f, px = w / 240f;
        String focus = calNoteField();
        drawCalHead(c, w, h, calNoteType, focus.equals("about") ? String.valueOf(256 - calAbout.length()) : "");
        float wrapTop = statusH(h) + calHeadH(h);
        float wrapH = 24.5f * vh;
        float left = 8 * px, right = w - 8 * px;
        // Layout pass: heights per row, then the HTML scroll rule (focused
        // field bottom pinned into view).
        String[] kinds = calNoteAlarm ? new String[]{"about", "date", "repeat", "alarm", "alarmtime"}
                : new String[]{"about", "date", "repeat", "alarm"};
        float labelH = 2.3f * vh, aboutH = 3.05f * vh, boxH = 5.0f * vh, plainH = 4.2f * vh, cycH = 3.0f * vh;
        float[] tops = new float[kinds.length], bots = new float[kinds.length];
        float y = 0;
        for (int i = 0; i < kinds.length; i++) {
            y += labelH;
            tops[i] = y;
            String k = kinds[i];
            float fh = k.equals("about") ? aboutH
                    : k.equals("date") ? (focus.equals("date") ? boxH : plainH)
                    : k.equals("alarmtime") ? (focus.equals("alarmtime") ? boxH : plainH)
                    : cycH;
            bots[i] = y + fh;
            y = bots[i];
        }
        int fi = Math.min(calNoteFocus, kinds.length - 1);
        float scroll = Math.max(0, tops[fi] - wrapH + (bots[fi] - tops[fi]) + 8 * px); // HTML scrollTop rule
        c.save();
        c.clipRect(0, wrapTop, w, wrapTop + wrapH);
        c.translate(0, wrapTop - scroll);
        y = 0;
        p.setTextAlign(Paint.Align.LEFT);
        for (int i = 0; i < kinds.length; i++) {
            String k = kinds[i];
            boolean fsel = i == fi;
            String label = k.equals("about") ? "Remind about:" : k.equals("date") ? "Date:"
                    : k.equals("repeat") ? "Repeat:" : k.equals("alarm") ? "Alarm:" : "Alarm time:";
            drawNfLabel(c, left, y + 0.4f * vh + 1.6f * vh * 0.78f, label, vh);
            y += labelH;
            if (k.equals("about")) {
                // HTML .nfField: dark rounded box, blue border when focused,
                // bold text plus a thin white cursor.
                float ft = y + 0.15f * vh, fb = ft + 2.9f * vh;
                p.setStyle(Paint.Style.FILL);
                p.setColor(Color.argb(140, 10, 16, 26)); // rgba(10,16,26,.55)
                c.drawRoundRect(new android.graphics.RectF(left, ft, right, fb), 5 * px, 5 * px, p);
                p.setStyle(Paint.Style.STROKE);
                p.setStrokeWidth(1 * px);
                p.setColor(Color.parseColor(fsel ? "#8FB4E8" : "#3A4A5A"));
                c.drawRoundRect(new android.graphics.RectF(left, ft, right, fb), 5 * px, 5 * px, p);
                p.setStyle(Paint.Style.FILL);
                p.setTypeface(Typeface.create("sans-serif-condensed", Typeface.NORMAL));
                p.setFakeBoldText(true);
                p.setColor(Color.WHITE);
                p.setTextSize(1.9f * vh);
                String t = calAbout.toString();
                float maxW = right - left - 12 * px;
                while (t.length() > 0 && p.measureText(t) > maxW) t = t.substring(1); // input scrolls left
                float base = ft + 0.3f * vh + 1.9f * vh * 0.78f;
                c.drawText(t, left + 6 * px, base, p);
                if (fsel) {
                    float cx = left + 6 * px + p.measureText(t) + 1 * px;
                    c.drawRect(cx, base - 1.6f * vh * 0.82f, cx + 1 * px, base + 1.6f * vh * 0.18f, p);
                }
                p.setFakeBoldText(false);
                p.setTypeface(Typeface.DEFAULT);
                y = fb;
            } else if (k.equals("date") || k.equals("alarmtime")) {
                boolean isDate = k.equals("date");
                String hint = isDate ? "DD-MM-YYYY" : "HH:MM";
                String val = isDate ? calNoteDateStr : calNoteTime;
                String sep = isDate ? "-" : ":";
                if (fsel) {
                    // HTML .nfBox: light gradient box, hint line, digit editor.
                    float bt = y + 0.15f * vh, bb = bt + 4.85f * vh;
                    android.graphics.LinearGradient g = new android.graphics.LinearGradient(0, bt, 0, bb,
                            Color.parseColor("#F2F6FB"), Color.parseColor("#CFDCEC"), android.graphics.Shader.TileMode.CLAMP);
                    p.setShader(g);
                    p.setStyle(Paint.Style.FILL);
                    c.drawRoundRect(new android.graphics.RectF(left, bt, right, bb), 5 * px, 5 * px, p);
                    p.setShader(null);
                    p.setTypeface(Typeface.create("sans-serif-condensed", Typeface.NORMAL));
                    p.setColor(Color.parseColor("#9AA7B5"));
                    p.setTextSize(1.5f * vh);
                    p.setTextAlign(Paint.Align.CENTER);
                    c.drawText(hint, w / 2f, bt + 0.4f * vh + 1.5f * vh * 0.78f, p);
                    p.setTextAlign(Paint.Align.LEFT);
                    // Digit editor: the focused pair sits on a #3867A0 chip.
                    String[] parts = val.split(isDate ? "-" : ":");
                    p.setFakeBoldText(true);
                    p.setTextSize(2.0f * vh);
                    float[] widths = new float[parts.length];
                    float tot = 0;
                    for (int pi2 = 0; pi2 < parts.length; pi2++) {
                        widths[pi2] = p.measureText(parts[pi2]);
                        tot += widths[pi2];
                    }
                    float sepW = p.measureText(sep);
                    tot += sepW * (parts.length - 1);
                    float sx = (w - tot) / 2f;
                    float vBase = bt + 0.4f * vh + 1.5f * vh * 1.05f + 0.35f * vh + 2.0f * vh * 0.82f;
                    for (int pi2 = 0; pi2 < parts.length; pi2++) {
                        if (pi2 == calNoteDigit) {
                            p.setStyle(Paint.Style.FILL);
                            p.setColor(Color.parseColor("#3867A0"));
                            c.drawRoundRect(new android.graphics.RectF(sx - 2 * px, vBase - 2.0f * vh * 0.85f, sx + widths[pi2] + 2 * px, vBase + 2.0f * vh * 0.25f), 2 * px, 2 * px, p);
                            p.setColor(Color.WHITE);
                        } else p.setColor(Color.BLACK);
                        c.drawText(parts[pi2], sx, vBase, p);
                        sx += widths[pi2];
                        if (pi2 < parts.length - 1) {
                            p.setColor(Color.BLACK);
                            c.drawText(sep, sx, vBase, p);
                            sx += sepW;
                        }
                    }
                    p.setFakeBoldText(false);
                    p.setTypeface(Typeface.DEFAULT);
                    y = bb;
                } else {
                    // HTML: unfocused date/time is the hint plus a plain value.
                    p.setTypeface(Typeface.create("sans-serif-condensed", Typeface.NORMAL));
                    p.setColor(Color.parseColor("#9AA7B5"));
                    p.setTextSize(1.5f * vh);
                    p.setTextAlign(Paint.Align.CENTER);
                    c.drawText(hint, w / 2f, y + 0.3f * vh + 1.5f * vh * 0.78f, p);
                    p.setFakeBoldText(true);
                    p.setColor(Color.WHITE);
                    p.setTextSize(2.0f * vh);
                    c.drawText(val, w / 2f, y + 0.3f * vh + 1.5f * vh * 1.05f + 0.2f * vh + 2.0f * vh * 0.82f, p);
                    p.setTextAlign(Paint.Align.LEFT);
                    p.setFakeBoldText(false);
                    p.setTypeface(Typeface.DEFAULT);
                    y += plainH;
                }
            } else {
                // HTML .nfCyc: dark rounded cycler, light gradient when focused.
                float ct = y + 0.15f * vh, cb = ct + 2.85f * vh;
                if (fsel) {
                    android.graphics.LinearGradient g = new android.graphics.LinearGradient(0, ct, 0, cb,
                            Color.parseColor("#F2F6FB"), Color.parseColor("#CFDCEC"), android.graphics.Shader.TileMode.CLAMP);
                    p.setShader(g);
                    p.setStyle(Paint.Style.FILL);
                    c.drawRoundRect(new android.graphics.RectF(left, ct, right, cb), 5 * px, 5 * px, p);
                    p.setShader(null);
                } else {
                    p.setStyle(Paint.Style.FILL);
                    p.setColor(Color.argb(140, 10, 16, 26));
                    c.drawRoundRect(new android.graphics.RectF(left, ct, right, cb), 5 * px, 5 * px, p);
                }
                p.setStyle(Paint.Style.STROKE);
                p.setStrokeWidth(1 * px);
                p.setColor(Color.parseColor("#3A4A5A"));
                c.drawRoundRect(new android.graphics.RectF(left, ct, right, cb), 5 * px, 5 * px, p);
                p.setStyle(Paint.Style.FILL);
                String val = k.equals("repeat") ? CAL_REPEATS[calNoteRepeat] : (calNoteAlarm ? "Alarm on" : "Alarm off");
                float mid = (ct + cb) / 2f;
                p.setTypeface(Typeface.create("sans-serif-condensed", Typeface.NORMAL));
                p.setColor(Color.parseColor("#CFE0F5"));
                p.setTextSize(1.4f * vh);
                p.setTextAlign(Paint.Align.LEFT);
                c.drawText("\u25C0", left + 8 * px, mid + 1.4f * vh * 0.35f, p);
                p.setTextAlign(Paint.Align.RIGHT);
                c.drawText("\u25B6", right - 8 * px, mid + 1.4f * vh * 0.35f, p);
                p.setTextAlign(Paint.Align.CENTER);
                p.setFakeBoldText(true);
                p.setTextSize(1.9f * vh);
                p.setColor(fsel ? Color.BLACK : Color.WHITE);
                c.drawText(val, w / 2f, mid + 1.9f * vh * 0.32f, p);
                p.setTextAlign(Paint.Align.LEFT);
                p.setFakeBoldText(false);
                p.setTypeface(Typeface.DEFAULT);
                y = cb;
            }
        }
        c.restore();
    }

    // HTML .overlay.calMenu: the floating dark panel (8% side insets, top 14%,
    // 6-row window, light gradient selection, optional icons/radios).
    private void drawCalMenuPanel(Canvas c, int w, int h, String[] items, int sel, Bitmap[] icons, String radioMode) {
        float vh = h / 100f, px = w / 240f;
        float left = w * 0.08f, right = w * 0.92f;
        float rowH = 3.3f * vh;
        int count = items.length;
        int visible = Math.min(count, 6); // HTML ov=6 window
        int first = Math.max(0, Math.min(sel - 5, count - visible));
        float panelH = visible * rowH;
        float top = Math.min(h * 0.14f, softTop(h) - panelH);
        android.graphics.Path clip = new android.graphics.Path();
        clip.addRoundRect(new android.graphics.RectF(left, top, right, top + panelH), 6 * px, 6 * px, android.graphics.Path.Direction.CW);
        c.save();
        c.clipPath(clip);
        p.setStyle(Paint.Style.FILL);
        p.setColor(Color.argb(235, 8, 12, 20)); // rgba(8,12,20,.92)
        c.drawRect(left, top, right, top + panelH, p);
        p.setTypeface(Typeface.create("sans-serif-condensed", Typeface.NORMAL));
        p.setFakeBoldText(true);
        p.setTextSize(1.8f * vh);
        p.setTextAlign(Paint.Align.LEFT);
        for (int i = 0; i < visible; i++) {
            int idx = first + i;
            float ry = top + i * rowH;
            boolean isSel = idx == sel;
            if (isSel) {
                android.graphics.LinearGradient g = new android.graphics.LinearGradient(0, ry, 0, ry + rowH,
                        Color.parseColor("#F2F6FB"), Color.parseColor("#CFDCEC"), android.graphics.Shader.TileMode.CLAMP);
                p.setShader(g);
                c.drawRect(left, ry, right, ry + rowH, p);
                p.setShader(null);
            }
            float tx = left + 10 * px;
            float base = ry + rowH * 0.68f;
            if (icons != null && idx < icons.length && icons[idx] != null) {
                float isz = 2.6f * vh;
                c.drawBitmap(icons[idx], null, new android.graphics.RectF(tx, ry + (rowH - isz) / 2, tx + isz, ry + (rowH + isz) / 2), null);
                tx += isz + 8 * px;
            }
            p.setColor(isSel ? Color.BLACK : Color.WHITE);
            if (radioMode != null) {
                boolean on = radioMode.equals("lang") ? items[idx].equals(writingLang)
                        : radioMode.equals("predstatus") ? (items[idx].equals("On")) == predictionOn
                        : items[idx].equals(predictionType);
                p.setTextSize(1.6f * vh);
                String glyph = on ? "\u25C9" : "\u25CB";
                c.drawText(glyph, tx, base, p);
                tx += p.measureText(glyph) + 8 * px;
                p.setTextSize(1.8f * vh);
            }
            c.drawText(items[idx], tx, base, p);
        }
        c.restore();
        p.setStyle(Paint.Style.STROKE);
        p.setStrokeWidth(1 * px);
        p.setColor(Color.parseColor("#3A4A5A"));
        c.drawRoundRect(new android.graphics.RectF(left, top, right, top + panelH), 6 * px, 6 * px, p);
        p.setStyle(Paint.Style.FILL);
        p.setFakeBoldText(false);
        p.setTypeface(Typeface.DEFAULT);
    }

