    // Faithful S40 Options popup: black header with a live item count, white
    // rows on the dark #111923 panel, inverted selection, right-edge scrollbar.
    private void drawOptions(Canvas c, int w, int h) {
        float top = statusH(h);
        float bot = softTop(h);
        float panelH = bot - top;
        p.setFakeBoldText(false);
        // Sim .optionsPanel: dark #111923 overlay.
        p.setStyle(Paint.Style.FILL);
        p.setColor(Color.parseColor("#111923"));
        c.drawRect(0, top, w, bot, p);
        // Sim .optionsHeader: 31px of the 320px screen, black, 'Options' left, count right.
        float headH = panelH * (31f / 320f);
        p.setColor(Color.BLACK);
        c.drawRect(0, top, w, top + headH, p);
        p.setTypeface(Typeface.create("sans-serif-condensed", Typeface.NORMAL));
        p.setColor(Color.WHITE);
        p.setTextSize(w * 0.079f);
        p.setTextAlign(Paint.Align.LEFT);
        c.drawText("Options", w * 0.02f, top + headH * 0.74f, p);
        p.setTextAlign(Paint.Align.RIGHT);
        c.drawText((optionsItems.length == 0 ? 0 : optionsSel + 1) + "-" + optionsItems.length, w * 0.98f, top + headH * 0.74f, p);
        // Sim .opt: fixed 34px rows from the top (no stretch), ov=6 window, bottom-pinned scroll.
        float listTop = top + headH;
        int count = optionsItems.length;
        int visible = Math.min(count, 6); // sim options panel ov=6
        float rowH = panelH * (34f / 320f);
        int first = Math.max(0, Math.min(optionsSel - 5, count - visible));
        for (int i = 0; i < visible; i++) {
            int idx = first + i;
            float ry = listTop + i * rowH;
            boolean sel = idx == optionsSel;
            if (sel) {
                // Sim Black.nth .opt.sel: silver gradient bar image, black normal-weight text.
                if (optionSelBar == null) optionSelBar = decodeIcon(OPTION_SEL_BAR_B64);
                if (optionSelBar != null) c.drawBitmap(optionSelBar, null, new android.graphics.RectF(0, ry, w, ry + rowH), null);
                else { p.setStyle(Paint.Style.FILL); p.setColor(Color.parseColor("#e8e8e8")); c.drawRect(0, ry, w, ry + rowH, p); }
            }
            // Sim: the loanediting panel renders its rows disabled (.opt.disabled #777).
            boolean dis = (loanEditing && optionsFrom == Screen.LOANCALC)
                    || (optionsFrom == Screen.LIST && listSection == 0 && row == 7 && "New e-mail".equals(optionsItems[idx])); // sim optionDisabled
            p.setColor(dis ? Color.parseColor("#777777") : (sel ? Color.BLACK : Color.WHITE));
            p.setTextSize(w * 0.075f);
            p.setTextAlign(Paint.Align.LEFT);
            c.drawText(optionsItems[idx], w * 0.033f, ry + rowH * 0.72f, p);
        }
        p.setTextAlign(Paint.Align.LEFT);
        p.setTypeface(Typeface.DEFAULT);
    }


    private void drawSoftkeys(Canvas c, int w, int h) {
        float top = softTop(h);
        p.setStyle(Paint.Style.FILL);
        p.setColor(COL_SOFT_BG);
        c.drawRect(0, top, w, h, p);
        String[] labels = softLabels();
        p.setTypeface(Typeface.create("sans-serif-condensed", Typeface.BOLD));
        // Sim v4.89: soft font is 18px at the 240px LCD = w*0.075 (not the taller fit I had).
        p.setTextSize(w * 0.075f);
        p.setColor(Color.WHITE);
        float baseline = top + (h - top) * 0.66f;
        // Measure each label so L/C/R can never collide: left and right capped at a
        // third of the width, center ellipsized between them, exactly like the S40 bar.
        float third = w * 0.31f;
        String l = ellipsize(labels[0], third, p);
        String r = ellipsize(labels[2], third, p);
        float lRight = w * 0.02f + p.measureText(l);
        float rLeft = w * 0.98f - p.measureText(r);
        String ctr = ellipsize(labels[1], Math.max(0, rLeft - lRight - w * 0.02f), p);
        p.setTextAlign(Paint.Align.LEFT);
        c.drawText(l, w * 0.02f, baseline, p);
        p.setTextAlign(Paint.Align.CENTER);
        c.drawText(ctr, w * 0.5f, baseline, p);
        p.setTextAlign(Paint.Align.RIGHT);
        c.drawText(r, w * 0.98f, baseline, p);
        p.setTextAlign(Paint.Align.LEFT);
        p.setTypeface(Typeface.DEFAULT);
    }

