    private void openOptions() {
        String[] items = optionsItemsFor(screen);
        if (items.length == 0) return;
        optionsFrom = screen;
        optionsItems = items;
        optionsSel = 0;
        screen = Screen.OPTIONS;
        invalidate();
    }

    private String[] softLabels() {
        // HTML: while a calendar overlay is up the softkeys belong to it.
        if (noteTypesOv || calDayPicker || (calOv.length() > 0 && !calOv.equals("matches"))) return new String[]{"", "Select", "Back"};
        if (calOv.equals("matches")) return new String[]{"", "Use", "Back"};
        if (composeExitConfirm) return new String[]{"Yes", "", "No"};
        if (symbolFlyout) return new String[]{"", "Select", "Back"};
        if (symOpen) return new String[]{"", "Use", "Back"};
        if (noteMarkMode) return new String[]{"Cancel", noteMarkStarted ? "Copy" : "Start", "Back"};
        if (bluetoothPrompt) return new String[]{"Yes", "", "No"};
        if (mailboxConfirm) return new String[]{"", "Yes", "No"}; // sim soft('','Yes','No')
        if (mailboxWizard) return new String[]{"", "", "Back"};
        if (imToast) return new String[]{"", "", ""}; // sim imtoast soft('','','')
        if (openingConvo) return new String[]{"", "", "Back"}; // sim openingconversation soft('','','Back')
        if (openingFolder) return new String[]{"", "", "Back"}; // sim openingfolder soft('','','Back')
        if (deleteNoteConfirm) return new String[]{"Yes", "", "No"};
        if (deleteNotesConfirm > 0) return new String[]{"", "Yes", "No"};
        switch (screen) {
            case IDLE: return locked ? new String[]{"Unlock", "", ""} : new String[]{"Go to", "Menu", "Names"};
            case INCALL: return new String[]{"Options", "Menu", callLoud ? "Handset" : "Loudsp."}; // HTML incall soft keys
            case OPTIONS: return new String[]{"", "Select", "Back"};
            case MENU: return new String[]{"Options", "Select", "Exit"};
            case GOTO: return new String[]{"Options", "Select", "Back"};
            case PROFILES: return new String[]{"Options", "Activate", "Back"};
            case ALARM: return new String[]{"Options", "Change", "Back"};
            case ALARM_EDIT: return new String[]{"Options", "Save", alarmDigits.length() > 0 ? "Clear" : "Back"};
            case CALC: return new String[]{"Options", "", calcActive ? "Clear" : "Exit"};
            case CAMERA: return new String[]{"Options", "Capture", "Back"};
            case VIDEOREC: return new String[]{"Options", videoRecording ? "Stop" : "Record", "Back"};
            case RADIO: return new String[]{"Options", radioPlaying ? "Stop" : "Play", "Back"};
            case MAPS: return new String[]{"Options", "Search", "Back"};
            case STOPWATCH: return new String[]{(swRunning || swElapsed > 0) ? "Options" : "", swRunning ? "Stop" : (swElapsed > 0 ? "Continue" : "Start"), "Back"};
            case SWTIMES: return new String[]{"", "Select", "Back"};
            case MEMSTATUS: return new String[]{"", "Select", "Back"};
            case MEMCARD: return new String[]{"", "", "Back"};
            case FOLDERNAME: return new String[]{"", "OK", folderTap.preview().length() > 0 ? "Clear" : "Back"};
            case CALNOTE:
                // HTML calnote soft: alarm-time blanks the left key; Clear/Cancel/Back on the right.
                return new String[]{calNoteField().equals("alarmtime") ? "" : "Options", "Save",
                        calNoteFocus == 0 && calAbout.length() > 0 ? "Clear" : (calNoteDirty ? "Cancel" : "Back")};
            case TODOEDIT: case TEXTNOTE:
                return new String[]{"Options", "Save", noteTap.preview().length() > 0 ? "Clear" : "Back"};
            case CALVIEW: return calNotesOnDay().isEmpty() ? new String[]{"", "", "Back"} : new String[]{"Options", "View", "Back"};
            case CALMONTH: return new String[]{"Options", "View", "Back"};
            case CALOPEN: return new String[]{"Options", "Edit", "Back"};
            case INSERTWORD: return new String[]{"", "Save", insertWord.length() > 0 ? "Clear" : "Back"};
            case NOTEVIEW: return new String[]{"Options", "Edit", "Back"};
            case NORMALTIMER: return new String[]{"", "OK", "Back"};
            case TIMERNOTE: return new String[]{"", "Start", timerTap.preview().length() > 0 ? "Clear" : "Back"};
            case INTERVALTIMER: return new String[]{"Options", intervalRunning ? "Stop" : "Change", "Back"};
            case CDSETTINGS: return new String[]{"", "Change", "Back"};
            case SCIENTIFIC: return new String[]{"Options", "Select", "Exit"}; // sim scientific soft
            case LOANINTRO: return new String[]{"", "OK", "Back"};
            case LOANCALC: { // Sim: Calculate only when 3 fields filled + current empty
                int filled = 0;
                for (String f : loanFields) if (!f.isEmpty()) filled++;
                boolean ready = filled == 3 && loanFields[loanField].isEmpty();
                return new String[]{"Options", ready ? "Calculate" : "", loanResult ? "Clear" : "Exit"};
            }
            case USEDETAILNUM: return new String[]{"", "Save", "Back"};
            case LOADINGNOTE: return new String[]{"", "", ""};
            case VOICEREC: return new String[]{"Options", voiceRecording ? "Stop" : "Record", "Back"};
            case BROWSER: return new String[]{"Options", "Open", "Back"}; // sim soft('Options','Open','Back')
            case URLENTRY: return new String[]{"Options", "Go", urlEntry.length() > 0 ? "Clear" : "Back"}; // sim label; RSK still backs out, as in the sim
            case APPDOWNLOADS: return new String[]{"", "Open", "Back"};
            case PLAYER: return new String[]{"Options", "", "Back"}; // sim soft('Options','','Back')
            case MUSICLIB: return new String[]{"Options", "Select", "Exit"};
            case ALLSONGS: return new String[]{"Options", "Play", "Back"};
            case LIBLIST: return new String[]{"Options", "Open", "Back"};
            case EQUALISER: return new String[]{"Options", "Activate", "Back"};
            case ITEMDETAIL: return new String[]{"", "", "Back"};
            case CONFIRM_DEL: return new String[]{"Yes", "", "No"};
            case LIST: {
                String centre = "Select";
                if (listSection == 11) centre = "Edit"; // Drafts
                else if ((listSection >= 12 && listSection <= 16) || listSection == 36 || listSection == 38 || listSection == 61) centre = "Open"; // Outbox/Sent/Saved/Templates/Saved messages/My folders/Gallery/Inbox
                else if (listSection == 34 || listSection == 35) centre = ""; // sim soft('Options','','Back')
                else if (listSection == 58 || listSection == 62) centre = ""; // sim soft('Options','','Back')
                else if (listSection == 42) centre = todoNotes.isEmpty() ? "Add" : "Open"; // sim to-do centre
                else if (listSection == 43) centre = noteTexts.isEmpty() ? "Add" : "View"; // sim notes centre
                if (listSection >= 25 && listSection <= 28) { // sim settings pages: blank LSK, OK/Cancel while dirty
                    boolean d = (listSection == 25 && generalDirty) || (listSection == 26 && textDirty)
                            || (listSection == 27 && mmsDirty) || (listSection == 28 && emailDirty);
                    return new String[]{"", d ? "OK" : "Select", d ? "Cancel" : "Back"};
                }
                if (listSection == 54) return new String[]{"", "Add", "Back"}; // sim emailmailboxes soft('','Add','Back')
                if (listSection == 55) return new String[]{"Options", "Save", "Back"}; // sim messagecentreedit soft('Options','Save','Back')
                if (listSection == 59) return new String[]{"Details", "", "Back"}; // sim messagelog soft('Details','','Back')
                if (listSection == 60) return new String[]{"", "", "Back"}; // sim folderdetails soft('','','Back')
                String left = optionsItemsFor(Screen.LIST).length > 0 ? "Options" : "";
                if (listSection == 43 && noteTexts.isEmpty()) left = ""; // sim notes-empty soft('','Add','Back')
                if (listSection == 40) left = ""; // sim phonememory soft('','Select','Back')
                return new String[]{left, centre, "Back"};
            }
            case THREADS: return new String[]{"Options", "Open", "Back"};
            case CONVERSATION:
                // HTML: Reply on received, Open on sent, Open on the empty placeholder.
                return new String[]{"Options", convoMsgs.isEmpty() ? "Open"
                        : (convoMsgs.get(Math.min(row, convoMsgs.size() - 1)).type == 2 ? "Open" : "Reply"), "Back"};
            case READ: return new String[]{"Options", readFromInbox ? "Reply" : "Send", "Back"};
            case COMPOSE_NUMBER:
                return new String[]{"Options", resolvedFocus() == 0 ? "Add" : (composeNumber.length() > 0 ? "Send" : "Add"),
                        (composeNumber.length() > 0 || composeTap.text().length() > 0) ? "Clear" : "Back"};
            case ADD_CONTACT:
                return new String[]{"Options", "Save",
                        editingContact ? "Back" :
                                ((nameTap.text().length() > 0 || contactNumber.length() > 0) ? "Clear" : "Back")};
            case COMPOSE_TEXT: return new String[]{"", "Send", "Back"};
            case DIALER: return new String[]{"Options", "Save", dialNumber.length() > 0 ? "Clear" : "Back"};
            case CALLLOG: return new String[]{"Options", "Call", "Back"};
            case CONTACTS: return new String[]{"Options", "Details", "Exit"};
            case CONTACT_CARD: return new String[]{"Options", "Call", "Back"};
            case CONTACTS_HOME: case CALLLOG_HOME: return new String[]{"Options", "Select", "Back"};
            default: return new String[]{"", "", "Back"};
        }
    }
